-- Squashed from 5 prior migrations (see git log) on 2026-05-04.
-- App: flight-search. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_flight_search DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.airports (
    iata_code text NOT NULL,
    icao_code text,
    name text NOT NULL,
    city text,
    country text,
    latitude double precision,
    longitude double precision,
    timezone text,
    major boolean DEFAULT false NOT NULL,
    popular boolean DEFAULT false NOT NULL,
    traffic_rank integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: flights; Type: TABLE; Schema: public; Owner: -
-- Per-flight inventory rows. Each row is one specific scheduled flight
-- on a specific date — the search handler filters by origin_iata,
-- destination_iata, depart_date, and cabin.
--
CREATE TABLE public.flights (
    id text NOT NULL,
    airline text NOT NULL,
    airline_code text,
    flight_number text NOT NULL,
    origin_iata text NOT NULL,
    origin_city text,
    destination_iata text NOT NULL,
    destination_city text,
    depart_date date NOT NULL,
    depart_at timestamp with time zone NOT NULL,
    arrive_at timestamp with time zone NOT NULL,
    duration_minutes integer NOT NULL,
    stops integer DEFAULT 0 NOT NULL,
    stop_airports jsonb DEFAULT '[]'::jsonb NOT NULL,
    cabin text DEFAULT 'economy'::text NOT NULL,
    price_cents integer NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    deal text,
    fare_class text,
    aircraft text,
    baggage_included boolean DEFAULT true NOT NULL,
    refundable boolean DEFAULT false NOT NULL,
    amenities jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


