--
-- Seed: flights — generate a 90-day calendar of inventory across the
-- routes used by the UI's hero/landing/sample/copy. Each route gets 3-4
-- carriers per day with realistic price variance, so any same-day or
-- near-future search returns multiple sortable results without
-- depending on a third-party flight API.
--
-- We use generate_series on (today, today+90) so seeds stay relevant
-- without manual touch-ups; each row's id is a deterministic hash of
-- the route + date + flight_number so the data is reproducible.
--
INSERT INTO public.flights
  (id, airline, airline_code, flight_number, origin_iata, origin_city, destination_iata, destination_city,
   depart_date, depart_at, arrive_at, duration_minutes, stops, stop_airports, cabin, price_cents, currency,
   deal, fare_class, aircraft, baggage_included, refundable, amenities)
SELECT
  encode(sha256(convert_to(t.origin_iata || t.destination_iata || (g)::text || t.flight_number, 'utf8')), 'hex'),
  t.airline, t.airline_code, t.flight_number,
  t.origin_iata, t.origin_city, t.destination_iata, t.destination_city,
  (CURRENT_DATE + g) AS depart_date,
  ((CURRENT_DATE + g) + t.depart_time) AT TIME ZONE 'UTC',
  ((CURRENT_DATE + g) + t.depart_time + (t.duration_minutes || ' minutes')::interval) AT TIME ZONE 'UTC',
  t.duration_minutes,
  t.stops,
  t.stop_airports::jsonb,
  t.cabin,
  t.price_cents + ((g % 7) * 1500),
  'USD',
  t.deal,
  t.fare_class,
  t.aircraft,
  t.baggage_included,
  t.refundable,
  t.amenities::jsonb
FROM generate_series(0, 90) g
CROSS JOIN (VALUES
